{"op":"define","frontend":"flow","source":"word invoice.queue-reminder-once(invoice: Invoice) -> String {
    effects fs.read fs.write
    doc "Queue a reminder once for an open invoice."

    let status = invoice::status(invoice)
    if ::equals(InvoiceStatus::value(status), "open") {
        let path = invoice::reminder-path(invoice::id(invoice))
        if file::exists?(path) {
            file::read(path)
        } else {
            file::write(path, "queued");
            "queued"
        }
    } else {
        "not-open"
    }
}

test invoice.queue-reminder-once/queues-new-open {
    invoice::queue-reminder-once(invoice::new(InvoiceId::new("inv-new"), InvoiceStatus::new("open"))) => "queued"
}

test invoice.queue-reminder-once/returns-existing-queued {
    file::write("outbox/invoice-reminders/inv-queued", "queued");
    invoice::queue-reminder-once(invoice::new(InvoiceId::new("inv-queued"), InvoiceStatus::new("open"))) => "queued"
}

test invoice.queue-reminder-once/preserves-other-marker {
    file::write("outbox/invoice-reminders/inv-marker", "sent-earlier");
    invoice::queue-reminder-once(invoice::new(InvoiceId::new("inv-marker"), InvoiceStatus::new("open"))) => "sent-earlier"
}

test invoice.queue-reminder-once/non-open-is-case-sensitive {
    invoice::queue-reminder-once(invoice::new(InvoiceId::new("inv-closed"), InvoiceStatus::new("Open"))) => "not-open"
}

example invoice.queue-reminder-once/queues-basic-reminder {
    invoice::queue-reminder-once(invoice::new(InvoiceId::new("inv-example"), InvoiceStatus::new("open"))) => "queued"
}"}

